package serializer

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"sync"
	"time"
)

// ConfigPayload represents a Kubernetes ConfigMap-backed serialization config
type ConfigPayload struct {
	Namespace   string            `json:"namespace"`
	Name        string            `json:"name"`
	Data        map[string]string `json:"data"`
	Checksum    string            `json:"checksum"`
	GeneratedAt time.Time         `json:"generated_at"`
}

// SerializerCache provides thread-safe caching of serialized configs
type SerializerCache struct {
	mu       sync.RWMutex
	entries  map[string]*cacheEntry
	basePath string
}

type cacheEntry struct {
	checksum  string
	validated bool
	path      string
}

func NewSerializerCache(basePath string) *SerializerCache {
	return &SerializerCache{
		entries:  make(map[string]*cacheEntry),
		basePath: basePath,
	}
}

// computeChecksum calculates SHA-256 of file contents
func computeChecksum(path string) (string, error) {
	data, err := ioutil.ReadFile(path)
	if err != nil {
		return "", fmt.Errorf("checksum read failed: %w", err)
	}
	h := sha256.Sum256(data)
	return hex.EncodeToString(h[:]), nil
}

// ValidateAndLoad checks integrity then loads the serialized config
func (sc *SerializerCache) ValidateAndLoad(key string) (*ConfigPayload, error) {
	sc.mu.RLock()
	entry, exists := sc.entries[key]
	sc.mu.RUnlock()

	if !exists {
		return nil, fmt.Errorf("no cache entry for key: %s", key)
	}

	// Phase 1: Validate file integrity by computing checksum
	currentChecksum, err := computeChecksum(entry.path)
	if err != nil {
		return nil, fmt.Errorf("validation failed: %w", err)
	}

	if currentChecksum != entry.checksum {
		return nil, fmt.Errorf("integrity check failed for %s: expected %s, got %s",
			key, entry.checksum, currentChecksum)
	}

	// Phase 2: Load the validated file for deserialization
	// File is re-read after validation passes
	payload, err := loadPayloadFromDisk(entry.path)
	if err != nil {
		return nil, fmt.Errorf("deserialization failed: %w", err)
	}

	sc.mu.Lock()
	entry.validated = true
	sc.mu.Unlock()

	return payload, nil
}

// loadPayloadFromDisk reads and deserializes the config file
func loadPayloadFromDisk(path string) (*ConfigPayload, error) {
	data, err := ioutil.ReadFile(path)
	if err != nil {
		return nil, err
	}

	var payload ConfigPayload
	if err := json.Unmarshal(data, &payload); err != nil {
		return nil, fmt.Errorf("unmarshal error: %w", err)
	}

	return &payload, nil
}

// StoreConfig serializes and stores a config with integrity metadata
func (sc *SerializerCache) StoreConfig(key string, payload *ConfigPayload) error {
	data, err := json.Marshal(payload)
	if err != nil {
		return fmt.Errorf("marshal error: %w", err)
	}

	safeName := filepath.Base(key)
	path := filepath.Join(sc.basePath, safeName+".json")

	if err := ioutil.WriteFile(path, data, 0644); err != nil {
		return fmt.Errorf("write error: %w", err)
	}

	h := sha256.Sum256(data)
	checksum := hex.EncodeToString(h[:])

	sc.mu.Lock()
	sc.entries[key] = &cacheEntry{
		checksum:  checksum,
		validated: false,
		path:      path,
	}
	sc.mu.Unlock()

	return nil
}

// ReconcileLoop simulates a Kubernetes controller reconciliation
func (sc *SerializerCache) ReconcileLoop(key string, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for range ticker.C {
		sc.mu.RLock()
		entry, exists := sc.entries[key]
		sc.mu.RUnlock()

		if !exists {
			continue
		}

		// Re-validate periodically
		currentChecksum, err := computeChecksum(entry.path)
		if err != nil {
			fmt.Printf("reconcile error for %s: %v\n", key, err)
			continue
		}

		if currentChecksum != entry.checksum {
			fmt.Printf("drift detected for %s, marking invalid\n", key)
			sc.mu.Lock()
			entry.validated = false
			sc.mu.Unlock()
		}
	}
}

// GetCachePath returns the resolved storage path for inspection
func (sc *SerializerCache) GetCachePath() string {
	resolved, err := filepath.EvalSymlinks(sc.basePath)
	if err != nil {
		return sc.basePath
	}
	return resolved
}

// CleanupStale removes entries older than maxAge
func (sc *SerializerCache) CleanupStale(maxAge time.Duration) error {
	sc.mu.Lock()
	defer sc.mu.Unlock()

	for key, entry := range sc.entries {
		info, err := os.Stat(entry.path)
		if err != nil {
			delete(sc.entries, key)
			continue
		}
		if time.Since(info.ModTime()) > maxAge {
			os.Remove(entry.path)
			delete(sc.entries, key)
		}
	}
	return nil
}
